import { readStorage, dayKey } from './storage.js';
import { WorkspaceStore, createWorkspace, dateOffset } from './WorkspaceStore.js';
const PAGES=['overview','plan','projects','habits','analytics'];
export class Dashboard {
  #widgets=[];#registry=new Map();
  constructor(container,{mode='demo',navigate=()=>{}}={}){this.container=container;this.mode=mode;this.navigate=navigate;this.events=new EventTarget();this.lifecycle=new AbortController();this.arranging=false;this.currentPage='overview';this.sessions=[];this.restoring=true;this.store=new WorkspaceStore(createWorkspace(mode==='demo'));}
  register(type,Widget,info){this.#registry.set(type,{Widget,...info});}
  get catalog(){return Array.from(this.#registry,([type,info])=>({type,...info}));}
  get widgets(){return [...this.#widgets];}
  get tasks(){return this.#widgets.filter(w=>w.type==='todo').flatMap(w=>w.tasks);}
  containerFor(widget){return document.querySelector(widget.page==='overview'&&widget.placement==='aside'?'#overview-aside':`#${widget.page}-widgets`)??document.querySelector('#overview-widgets');}
  addWidget(type,config={}){const entry=this.#registry.get(type);if(!entry)throw new Error('Неизвестный тип виджета');if(this.#widgets.length>=48)throw new Error('На панели уже 48 виджетов');const widget=new entry.Widget({...config,id:crypto.randomUUID(),type},this);widget.page=PAGES.includes(config.page)?config.page:this.currentPage;widget.placement=widget.page==='overview'&&(config.placement==='aside'||(!config.placement&&['focus','calendar','deadlines'].includes(type)))?'aside':'main';this.#widgets.push(widget);this.containerFor(widget).append(widget.render());this.updateCount();this.save();return widget;}
  removeWidget(id){const index=this.#widgets.findIndex(w=>w.id===id);if(index<0)return;const[widget]=this.#widgets.splice(index,1);widget.destroy();this.updateCount();this.save();const target=this.#widgets.find(w=>w.page===this.currentPage);(target?.minimizeButton??document.querySelector('#add-widget')).focus();this.announce(`Виджет «${widget.title}» удалён`);}
  moveWidget(id,direction){const widget=this.#widgets.find(w=>w.id===id);if(!widget)return;const siblings=this.#widgets.filter(w=>w.page===widget.page&&w.placement===widget.placement);const index=siblings.indexOf(widget),next=index+direction;if(next<0||next>=siblings.length)return;const first=this.#widgets.indexOf(widget),second=this.#widgets.indexOf(siblings[next]);const focus=document.activeElement;[this.#widgets[first],this.#widgets[second]]=[this.#widgets[second],this.#widgets[first]];this.#widgets.forEach(w=>this.containerFor(w).append(w.root));focus?.focus();this.save();this.announce('Порядок виджетов изменён');}
  setArranging(value){this.arranging=value;document.querySelectorAll('.dashboard').forEach(grid=>grid.classList.toggle('arranging',value));this.#widgets.forEach(w=>w.setArranging(value));}
  showPage(page){this.currentPage=page;this.updateCount();}
  restore(){let data;try{const saved=JSON.parse(localStorage.getItem(`dayform.v2.${this.mode}`));if(saved?.version===2&&Array.isArray(saved.widgets))data=saved;}catch{}let legacy=this.mode==='personal'&&!data?readStorage():null;if(data){this.store=new WorkspaceStore(data.model);this.sessions=this.validateSessions(data.sessions);for(const config of data.widgets.slice(0,48))if(config&&this.#registry.has(config.type)){try{this.addWidget(config.type,{state:config.state&&typeof config.state==='object'?config.state:{},page:config.page,placement:config.placement,minimized:!!config.minimized});}catch(error){console.warn('Пропущен повреждённый виджет',error);}}}else{this.store=new WorkspaceStore(createWorkspace(this.mode==='demo'));if(this.mode==='demo'){this.sessions=Array.from({length:28},(_,i)=>{const date=dateOffset(-i);const minutes=[75,120,90,150,45,100,60][i%7];return [{date,minutes:Math.min(45,minutes),category:'Творчество'},{date,minutes:Math.min(45,Math.max(15,minutes-45)),category:i%2?'Развитие':'Личное'}];}).flat();}else if(legacy)this.sessions=this.validateSessions(legacy.sessions);this.addDefaults(legacy);}
    this.store.addEventListener('change',()=>this.save(),{signal:this.lifecycle.signal});this.restoring=false;this.save();this.updateCount();}
  validateSessions(input){return(Array.isArray(input)?input:[]).filter(s=>s&&typeof s.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&Number.isFinite(s.minutes)&&s.minutes>0&&s.minutes<=45).slice(-2000).map(s=>({date:s.date,minutes:s.minutes,category:['Творчество','Развитие','Личное'].includes(s.category)?s.category:'Личное'}));}
  addDefaults(legacy){const add=(type,page,state={},placement)=>this.addWidget(type,{page,state,placement});['rhythm','schedule','projects'].forEach(type=>add(type,'overview'));['focus','calendar','deadlines'].forEach(type=>add(type,'overview',{},'aside'));const tasks=this.mode==='demo'?{tasks:[['Собрать идеи для главного экрана',true,'normal'],['Оформить один кейс в портфолио',false,'high'],['Прочитать 20 страниц',false,'normal'],['Прогуляться без телефона',false,'low']].map(([text,done,priority])=>({id:crypto.randomUUID(),text,done,priority,date:dayKey(),completedAt:done?dayKey():null}))}:{};const oldTodos=legacy?.widgets.filter(w=>w.type==='todo')??[];if(oldTodos.length)oldTodos.forEach(w=>add('todo','plan',w.state));else add('todo','plan',tasks);add('schedule','plan');const oldNotes=legacy?.widgets.filter(w=>w.type==='note')??[];if(oldNotes.length)oldNotes.forEach(w=>add('note','plan',w.state));else add('note','plan',this.mode==='demo'?{text:'Не пытаться сделать всё. Сегодня главное — закончить один хороший кейс.\n\nИдея: больше воздуха, меньше лишних деталей.'}:{});['weather','air','quote'].forEach(type=>add(type,'plan',legacy?.widgets.find(w=>w.type===type)?.state??{}));add('board','projects');add('projects','projects');add('balance','projects');add('habits','habits');add('heatmap','habits');add('quote','habits');['trend','distribution','balance','heatmap'].forEach(type=>add(type,'analytics'));if(legacy){for(const widget of legacy.widgets.filter(w=>w.type==='habit'))add('habit','habits',widget.state);const oldFocus=legacy.widgets.find(w=>w.type==='focus');if(oldFocus){const focus=this.#widgets.find(w=>w.type==='focus');this.removeWidget(focus.id);add('focus','overview',oldFocus.state,'aside');}}}
  updateCount(){const count=this.#widgets.filter(w=>w.page===this.currentPage).length;document.querySelector('#widget-count').textContent=count;document.querySelector('#empty-dashboard').hidden=count>0;}
  recordSession(minutes,category='Личное'){this.sessions.push({date:dayKey(),minutes,category});this.sessions=this.sessions.slice(-2000);this.save();}
  announce(text){document.querySelector('#announcement').textContent=text;}
  save(){if(this.restoring)return;let success=true;try{localStorage.setItem(`dayform.v2.${this.mode}`,JSON.stringify({version:2,widgets:this.#widgets.map(w=>w.serialize()),sessions:this.sessions,model:this.store.data}));}catch{success=false;}document.querySelector('#save-status').textContent=success?'Сохранено':'Не удалось сохранить';this.events.dispatchEvent(new Event('data'));}
  destroy({save=true}={}){if(save)this.save();this.lifecycle.abort();this.#widgets.forEach(w=>w.destroy());this.#widgets=[];}
}
